[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ScreenVault — UI & UX Design Inspiration for Mobile & Web Apps</title>
<meta name="description" content="Save hours of UI & UX research with a library of 400,000+ fully searchable mobile & web app screenshots.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: #141414; background: #fff; line-height: 1.6; overflow-x: hidden; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }
ul { list-style: none; }

/* ===== VARIABLES ===== */
:root {
  --accent: #6C5CE7;
  --accent-hover: #5A4BD1;
  --accent-light: rgba(108, 92, 231, 0.08);
  --accent-glow: rgba(108, 92, 231, 0.15);
  --dark: #141414;
  --gray-900: #1a1a1a;
  --gray-700: #444;
  --gray-600: #555;
  --gray-500: #777;
  --gray-400: #999;
  --gray-300: #ccc;
  --gray-200: #e5e5e5;
  --gray-100: #f5f5f5;
  --gray-50: #fafafa;
  --white: #ffffff;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.1);
  --shadow-card: 0 1px 4px rgba(0,0,0,0.04), 0 4px 16px rgba(0,0,0,0.06);
  --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

/* ===== UTILITIES ===== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section-padding { padding: 100px 0; }
.section-label {
  font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--accent); margin-bottom: 16px;
}
.section-title {
  font-size: clamp(32px, 5vw, 48px); font-weight: 800; line-height: 1.15;
  letter-spacing: -0.025em; color: var(--dark); margin-bottom: 16px;
}
.section-subtitle {
  font-size: 18px; color: var(--gray-600); max-width: 560px; line-height: 1.6;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font-size: 15px; font-weight: 600; border-radius: var(--radius-full);
  padding: 14px 28px; transition: all var(--transition); white-space: nowrap;
}
.btn-primary {
  background: var(--accent); color: var(--white);
  box-shadow: 0 2px 8px rgba(108, 92, 231, 0.3);
}
.btn-primary:hover { background: var(--accent-hover); box-shadow: 0 4px 16px rgba(108, 92, 231, 0.4); transform: translateY(-1px); }
.btn-secondary {
  background: var(--white); color: var(--dark);
  border: 1.5px solid var(--gray-200);
}
.btn-secondary:hover { border-color: var(--gray-300); background: var(--gray-50); }
.btn-ghost { color: var(--gray-600); padding: 14px 20px; }
.btn-ghost:hover { color: var(--dark); }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--dark); color: var(--white); text-align: center;
  padding: 10px 24px; font-size: 13px; font-weight: 500; letter-spacing: 0.02em;
}
.announcement-bar span { color: var(--accent); margin-right: 4px; }
.announcement-bar a { color: var(--white); text-decoration: underline; text-underline-offset: 2px; opacity: 0.9; margin-left: 8px; }
.announcement-bar a:hover { opacity: 1; }

/* ===== HEADER / NAV ===== */
.header {
  position: sticky; top: 0; z-index: 100; background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 64px;
}
.logo { font-size: 20px; font-weight: 800; letter-spacing: -0.03em; display: flex; align-items: center; gap: 8px; }
.logo-icon {
  width: 32px; height: 32px; background: var(--accent); border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
}
.logo-icon svg { width: 18px; height: 18px; }
.nav-links { display: flex; align-items: center; gap: 8px; }
.nav-links a { font-size: 14px; font-weight: 500; color: var(--gray-600); padding: 8px 14px; border-radius: var(--radius-full); transition: all var(--transition); }
.nav-links a:hover { color: var(--dark); background: var(--gray-100); }
.nav-cta { background: var(--dark) !important; color: var(--white) !important; padding: 8px 18px !important; }
.nav-cta:hover { background: var(--gray-900) !important; }
.mobile-menu-btn { display: none; padding: 8px; }
.mobile-menu-btn span { display: block; width: 20px; height: 2px; background: var(--dark); margin: 4px 0; border-radius: 2px; transition: all var(--transition); }

/* ===== HERO ===== */
.hero { padding: 80px 0 60px; text-align: center; position: relative; overflow: hidden; }
.hero::before {
  content: ''; position: absolute; top: -200px; left: 50%; transform: translateX(-50%);
  width: 800px; height: 800px; background: radial-gradient(circle, var(--accent-glow) 0%, transparent 70%);
  pointer-events: none; z-index: 0;
}
.hero .container { position: relative; z-index: 1; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px; background: var(--accent-light);
  color: var(--accent); font-size: 13px; font-weight: 600; padding: 8px 16px;
  border-radius: var(--radius-full); margin-bottom: 28px; border: 1px solid rgba(108, 92, 231, 0.12);
}
.hero-badge svg { width: 14px; height: 14px; }
.hero h1 {
  font-size: clamp(40px, 7vw, 72px); font-weight: 800; line-height: 1.05;
  letter-spacing: -0.035em; margin-bottom: 20px; max-width: 800px; margin-left: auto; margin-right: auto;
}
.hero h1 .accent-word { color: var(--accent); }
.hero-subtitle {
  font-size: clamp(16px, 2.5vw, 20px); color: var(--gray-600); max-width: 540px;
  margin: 0 auto 36px; line-height: 1.6;
}
.hero-ctas { display: flex; align-items: center; justify-content: center; gap: 12px; flex-wrap: wrap; }
.hero-ctas .btn-primary { padding: 16px 32px; font-size: 16px; }
.hero-ctas .btn-secondary { padding: 16px 32px; font-size: 16px; }
.hero-visual {
  margin-top: 64px; position: relative; border-radius: var(--radius-xl);
  overflow: hidden; box-shadow: var(--shadow-lg); border: 1px solid var(--gray-200);
  max-width: 960px; margin-left: auto; margin-right: auto;
  background: var(--gray-100); aspect-ratio: 16/9;
  display: flex; align-items: center; justify-content: center;
}
.hero-visual-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; padding: 16px; width: 100%;
}
.hero-thumb {
  background: var(--gray-200); border-radius: var(--radius-sm); aspect-ratio: 9/16;
  animation: shimmer 2s infinite; position: relative; overflow: hidden;
}
.hero-thumb::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
  animation: shimmerSlide 2s infinite;
}
@keyframes shimmerSlide { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
.hero-thumb:nth-child(2) { animation-delay: 0.15s; }
.hero-thumb:nth-child(2)::after { animation-delay: 0.15s; }
.hero-thumb:nth-child(3) { animation-delay: 0.3s; }
.hero-thumb:nth-child(3)::after { animation-delay: 0.3s; }
.hero-thumb:nth-child(4) { animation-delay: 0.45s; }
.hero-thumb:nth-child(4)::after { animation-delay: 0.45s; }

/* ===== TRUSTED BY / LOGO BAR ===== */
.trusted-by { padding: 48px 0 64px; }
.trusted-by-label {
  font-size: 13px; font-weight: 500; color: var(--gray-400); text-transform: uppercase;
  letter-spacing: 0.1em; text-align: center; margin-bottom: 28px;
}
.logo-row {
  display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap;
  opacity: 0.5;
}
.logo-row .brand-logo {
  font-size: 18px; font-weight: 700; color: var(--gray-500); letter-spacing: -0.02em;
  transition: opacity var(--transition);
}
.logo-row .brand-logo:hover { opacity: 0.8; }

/* ===== STATS ===== */
.stats-section { padding: 80px 0; background: var(--gray-50); border-top: 1px solid var(--gray-200); border-bottom: 1px solid var(--gray-200); }
.stats-header { text-align: center; margin-bottom: 56px; }
.stats-header .section-title { margin-bottom: 0; }
.stats-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px;
  max-width: 800px; margin: 0 auto;
}
.stat-card {
  text-align: center; padding: 32px 16px;
  background: var(--white); border-radius: var(--radius-lg); border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.stat-card:hover { border-color: var(--accent); box-shadow: 0 4px 20px var(--accent-glow); }
.stat-number {
  font-size: clamp(36px, 5vw, 56px); font-weight: 800; letter-spacing: -0.03em;
  color: var(--dark); line-height: 1; margin-bottom: 8px;
  font-variant-numeric: tabular-nums;
}
.stat-number .plus { color: var(--accent); }
.stat-label { font-size: 15px; font-weight: 500; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.05em; }

/* ===== FEATURES — SEARCH ===== */
.features-search { padding: 100px 0; }
.features-search-header { margin-bottom: 48px; }
.search-tabs {
  display: flex; gap: 4px; background: var(--gray-100); border-radius: var(--radius-full);
  padding: 4px; width: fit-content; margin-bottom: 24px; flex-wrap: wrap;
}
.search-tab {
  padding: 10px 20px; font-size: 14px; font-weight: 500; color: var(--gray-600);
  border-radius: var(--radius-full); transition: all var(--transition);
}
.search-tab:hover { color: var(--dark); }
.search-tab.active { background: var(--white); color: var(--dark); box-shadow: var(--shadow-sm); }
.filter-pills {
  display: flex; gap: 8px; overflow-x: auto; padding-bottom: 8px;
  scrollbar-width: none; -ms-overflow-style: none; margin-bottom: 32px;
}
.filter-pills::-webkit-scrollbar { display: none; }
.filter-pill {
  padding: 8px 18px; font-size: 13px; font-weight: 500; color: var(--gray-600);
  border: 1.5px solid var(--gray-200); border-radius: var(--radius-full);
  white-space: nowrap; transition: all var(--transition); flex-shrink: 0;
}
.filter-pill:hover { border-color: var(--gray-400); color: var(--dark); }
.filter-pill.active {
  background: var(--accent); color: var(--white); border-color: var(--accent);
}
.screenshot-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 12px;
}
.screenshot-card {
  background: var(--gray-100); border-radius: var(--radius-md); aspect-ratio: 9/16;
  border: 1px solid var(--gray-200); overflow: hidden; position: relative;
  transition: all var(--transition);
}
.screenshot-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); border-color: var(--gray-300); }
.screenshot-card-inner {
  width: 100%; height: 100%; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 8px; padding: 16px;
}
.screenshot-card-icon {
  width: 32px; height: 32px; background: var(--gray-200); border-radius: var(--radius-sm);
}
.screenshot-card-lines { width: 60%; display: flex; flex-direction: column; gap: 4px; }
.screenshot-card-line { height: 4px; background: var(--gray-200); border-radius: 2px; }
.screenshot-card-line:nth-child(2) { width: 75%; }
.screenshot-card-line:nth-child(3) { width: 50%; }
.screenshot-card-label {
  position: absolute; bottom: 0; left: 0; right: 0; padding: 12px;
  background: linear-gradient(transparent, rgba(0,0,0,0.6));
  color: white; font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
}
.grid-fade-enter { animation: gridFadeIn 300ms ease-out; }
@keyframes gridFadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== FEATURES — FLOWS ===== */
.features-flows { padding: 100px 0; background: var(--gray-50); border-top: 1px solid var(--gray-200); }
.features-flows-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
}
.flows-content { max-width: 480px; }
.flows-toggle {
  display: flex; gap: 4px; background: var(--gray-100); border-radius: var(--radius-full);
  padding: 4px; width: fit-content; margin: 28px 0;
  border: 1px solid var(--gray-200);
}
.flows-toggle-btn {
  padding: 10px 24px; font-size: 14px; font-weight: 500; color: var(--gray-500);
  border-radius: var(--radius-full); transition: all var(--transition);
}
.flows-toggle-btn:hover { color: var(--dark); }
.flows-toggle-btn.active { background: var(--white); color: var(--dark); box-shadow: var(--shadow-sm); }
.flows-description { font-size: 15px; color: var(--gray-600); line-height: 1.7; }
.flows-visual {
  background: var(--white); border-radius: var(--radius-xl); border: 1px solid var(--gray-200);
  padding: 24px; box-shadow: var(--shadow-card); min-height: 400px;
  display: flex; align-items: center; justify-content: center;
}
.flow-screens {
  display: flex; gap: 12px; align-items: center; width: 100%;
  transition: all 300ms ease;
}
.flow-screen {
  flex: 1; background: var(--gray-100); border-radius: var(--radius-md);
  aspect-ratio: 9/16; border: 1px solid var(--gray-200);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 12px; gap: 6px; position: relative;
}
.flow-screen-dot { width: 24px; height: 24px; background: var(--gray-200); border-radius: 50%; }
.flow-screen-bar { width: 60%; height: 4px; background: var(--gray-200); border-radius: 2px; }
.flow-screen-bar.short { width: 40%; }
.flow-arrow {
  flex-shrink: 0; width: 24px; height: 24px; color: var(--gray-400);
  display: flex; align-items: center; justify-content: center;
}
.flow-arrow svg { width: 16px; height: 16px; }
.flow-video-indicator {
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 40px; height: 40px; background: var(--accent); border-radius: 50%;
  display: flex; align-items: center; justify-content: center; opacity: 0;
  transition: opacity var(--transition);
}
.flow-video-indicator svg { width: 16px; height: 16px; color: white; margin-left: 2px; }
.flows-visual.video-mode .flow-video-indicator { opacity: 1; }
.flows-visual.video-mode .flow-screen { background: var(--dark); border-color: var(--gray-700); }
.flows-visual.video-mode .flow-screen-dot { background: var(--gray-600); }
.flows-visual.video-mode .flow-screen-bar { background: var(--gray-600); }
.flow-hotspot {
  position: absolute; bottom: 16px; left: 50%; transform: translateX(-50%);
  width: 32px; height: 32px; border: 2px solid var(--accent); border-radius: 50%;
  display: flex; align-items: center; justify-content: center; opacity: 0;
  transition: opacity var(--transition); animation: hotspotPulse 2s infinite;
}
.flow-hotspot::after { content: ''; width: 8px; height: 8px; background: var(--accent); border-radius: 50%; }
.flows-visual.prototype-mode .flow-hotspot { opacity: 1; }
@keyframes hotspotPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(108, 92, 231, 0.3); }
  50% { box-shadow: 0 0 0 8px rgba(108, 92, 231, 0); }
}

/* ===== FEATURES — TOOLS ===== */
.features-tools { padding: 100px 0; }
.features-tools-header { text-align: center; margin-bottom: 56px; }
.tools-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.tool-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-xl);
  padding: 32px; transition: all var(--transition); position: relative; overflow: hidden;
}
.tool-card:hover { border-color: var(--accent); box-shadow: 0 8px 32px var(--accent-glow); transform: translateY(-4px); }
.tool-card-icon {
  width: 48px; height: 48px; background: var(--accent-light); border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center; margin-bottom: 20px;
}
.tool-card-icon svg { width: 24px; height: 24px; color: var(--accent); }
.tool-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 10px; letter-spacing: -0.01em; }
.tool-card p { font-size: 14px; color: var(--gray-600); line-height: 1.65; }
.tool-card-visual {
  margin-top: 24px; background: var(--gray-50); border-radius: var(--radius-md);
  border: 1px solid var(--gray-200); aspect-ratio: 16/10; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.tool-card-visual-inner { padding: 16px; width: 100%; }
.tool-visual-row { display: flex; gap: 8px; align-items: center; margin-bottom: 8px; }
.tool-visual-square { width: 28px; height: 28px; background: var(--gray-200); border-radius: 6px; flex-shrink: 0; }
.tool-visual-line { height: 6px; background: var(--gray-200); border-radius: 3px; flex: 1; }
.tool-visual-line.w60 { max-width: 60%; }
.tool-visual-line.w40 { max-width: 40%; }
.tool-visual-btn { height: 28px; background: var(--accent-light); border-radius: 6px; width: 80px; }

/* ===== TESTIMONIALS ===== */
.testimonials-section { padding: 100px 0; background: var(--gray-50); border-top: 1px solid var(--gray-200); overflow: hidden; }
.testimonials-header { text-align: center; margin-bottom: 56px; }
.marquee-container { display: flex; flex-direction: column; gap: 20px; }
.marquee-row {
  display: flex; gap: 20px; width: max-content;
}
.marquee-row-1 { animation: marqueeLeft 60s linear infinite; }
.marquee-row-2 { animation: marqueeRight 65s linear infinite; }
@keyframes marqueeLeft { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
@keyframes marqueeRight { 0% { transform: translateX(-50%); } 100% { transform: translateX(0); } }
.testimonial-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 28px; width: 380px; flex-shrink: 0; transition: all var(--transition);
}
.testimonial-card:hover { border-color: var(--accent); box-shadow: 0 4px 20px var(--accent-glow); }
.testimonial-text { font-size: 14px; color: var(--gray-700); line-height: 1.7; margin-bottom: 20px; }
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.testimonial-avatar {
  width: 40px; height: 40px; border-radius: 50%; background: var(--accent-light);
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; font-weight: 700; color: var(--accent);
}
.testimonial-info { display: flex; flex-direction: column; }
.testimonial-name { font-size: 14px; font-weight: 600; color: var(--dark); }
.testimonial-role { font-size: 12px; color: var(--gray-500); }

/* ===== CTA ===== */
.cta-section { padding: 100px 0 0; text-align: center; overflow: hidden; }
.cta-content { margin-bottom: 64px; }
.cta-content .section-title { margin-bottom: 16px; }
.cta-content p { font-size: 17px; color: var(--gray-600); max-width: 520px; margin: 0 auto 32px; line-height: 1.6; }
.cta-buttons { display: flex; align-items: center; justify-content: center; gap: 12px; flex-wrap: wrap; }
.brand-marquee { padding: 48px 0; }
.brand-marquee-row { display: flex; gap: 16px; width: max-content; margin-bottom: 16px; }
.brand-marquee-row-1 { animation: marqueeLeft 45s linear infinite; }
.brand-marquee-row-2 { animation: marqueeRight 50s linear infinite; }
.brand-icon {
  width: 56px; height: 56px; background: var(--gray-100); border-radius: var(--radius-md);
  border: 1px solid var(--gray-200); display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; font-size: 11px; font-weight: 700; color: var(--gray-500);
  transition: all var(--transition);
}
.brand-icon:hover { border-color: var(--accent); background: var(--accent-light); color: var(--accent); }

/* ===== FOOTER ===== */
.footer {
  background: var(--dark); color: var(--white); padding: 64px 0 32px;
}
.footer-inner { display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px; }
.footer-brand p { font-size: 14px; color: var(--gray-500); margin-top: 16px; line-height: 1.6; max-width: 280px; }
.footer-col h4 { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: var(--gray-400); margin-bottom: 16px; }
.footer-col a { display: block; font-size: 14px; color: var(--gray-500); padding: 4px 0; transition: color var(--transition); }
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: 32px; border-top: 1px solid rgba(255,255,255,0.08);
  font-size: 13px; color: var(--gray-500); flex-wrap: wrap; gap: 16px;
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { color: var(--gray-500); transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--white); }
.footer-logo { font-size: 18px; font-weight: 800; color: var(--white); letter-spacing: -0.03em; display: flex; align-items: center; gap: 8px; }
