<script>
(function() {
  'use strict';

  // ===== MOBILE MENU =====
  const menuBtn = document.getElementById('mobileMenuBtn');
  const navLinks = document.getElementById('navLinks');
  menuBtn.addEventListener('click', () => {
    navLinks.classList.toggle('open');
    const spans = menuBtn.querySelectorAll('span');
    if (navLinks.classList.contains('open')) {
      spans[0].style.transform = 'rotate(45deg) translate(4px, 4px)';
      spans[1].style.opacity = '0';
      spans[2].style.transform = 'rotate(-45deg) translate(4px, -4px)';
    } else {
      spans[0].style.transform = '';
      spans[1].style.opacity = '';
      spans[2].style.transform = '';
    }
  });

  // ===== SCROLL ANIMATIONS =====
  const fadeObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        fadeObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
  document.querySelectorAll('.fade-up').forEach(el => fadeObserver.observe(el));

  // ===== STAT COUNTER ANIMATION =====
  function animateCounter(el) {
    const target = parseInt(el.dataset.target);
    const duration = 2000;
    const start = performance.now();
    const format = (n) => n.toLocaleString('en-US');

    function tick(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = format(Math.round(target * eased));
      if (progress < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  const statsObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const counters = entry.target.querySelectorAll('.counter');
        counters.forEach((c, i) => {
          setTimeout(() => animateCounter(c), i * 150);
        });
        statsObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });
  statsObserver.observe(document.getElementById('statsSection'));

  // ===== SEARCH TABS =====
  const tabLabels = { screens: 'Screens', elements: 'UI Elements', flows: 'Flows', text: 'Text in Screenshot' };
  let activeTab = 'screens';
  let activeFilter = 'Profile';

  document.querySelectorAll('.search-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.search-tab').forEach(t => {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');
      activeTab = tab.dataset.tab;
      renderGrid();
    });
  });

  // ===== FILTER PILLS =====
  document.querySelectorAll('.filter-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      document.querySelectorAll('.filter-pill').forEach(p => {
        p.classList.remove('active');
        p.setAttribute('aria-selected', 'false');
      });
      pill.classList.add('active');
      pill.setAttribute('aria-selected', 'true');
      activeFilter = pill.dataset.filter;
      renderGrid();
    });
  });

  // ===== SCREENSHOT GRID RENDERING =====
  const appNames = ['Spotify', 'Airbnb', 'Uber', 'Nike', 'Notion', 'Figma', 'Slack', 'Discord', 'Linear', 'Stripe', 'Duolingo', 'Calm'];
  const colors = ['#1DB954','#FF5A5F','#000','#111','#F7F6F3','#A259FF','#4A154B','#5865F2','#5E6AD2','#635BFF','#58CC02','#4B8BBE'];

  function renderGrid() {
    const grid = document.getElementById('screenshotGrid');
    grid.innerHTML = '';
    const count = window.innerWidth < 768 ? 6 : 8;
    const seed = (activeTab + activeFilter).length;
    for (let i = 0; i < count; i++) {
      const idx = (seed + i * 3) % appNames.length;
      const card = document.createElement('div');
      card.className = 'screenshot-card grid-fade-enter';
      card.innerHTML = `
        <div class="screenshot-card-inner">
          <div class="screenshot-card-icon" style="background:${colors[idx]}20; border-radius:8px;"></div>
          <div class="screenshot-card-lines">
            <div class="screenshot-card-line" style="background:${colors[idx]}30"></div>
            <div class="screenshot-card-line" style="background:${colors[idx]}20"></div>
            <div class="screenshot-card-line" style="background:${colors[idx]}15"></div>
          </div>
        </div>
        <div class="screenshot-card-label">${appNames[idx]} &middot; ${activeFilter}</div>
      `;
      card.style.animationDelay = `${i * 40}ms`;
      grid.appendChild(card);
    }
  }
  renderGrid();

  // ===== FLOWS TOGGLE =====
  const flowsVisual = document.getElementById('flowsVisual');
  const flowsDesc = document.getElementById('flowsDescription');
  const flowsDescriptions = {
    video: 'Experience flows the way they were meant to be experienced, complete with transitions, micro-interactions, and animations.',
    prototype: 'Walk through flows, step by step, by using the interactive hotspots at your own preferred pace.'
  };

  document.querySelectorAll('.flows-toggle-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.flows-toggle-btn').forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');
      const mode = btn.dataset.mode;
      flowsVisual.className = 'flows-visual ' + mode + '-mode fade-up delay-1 visible';
      flowsDesc.textContent = flowsDescriptions[mode];
    });
  });

  // ===== TESTIMONIALS MARQUEE =====
  const testimonials = [
    { name: 'Sebastian Speier', company: 'Shop', initial: 'S', text: 'ScreenVault is a great resource and it always comes in handy to see what the best practices or standards are for mobile patterns in our current landscape.' },
    { name: 'Meng To', company: 'DesignCode', initial: 'M', text: "ScreenVault is a game-changer for designers looking to step up their understanding of UX and UI design patterns. It's so massive, meticulously organized, has deep user flows and even a Figma plugin! It's indispensable in the modern designer's toolbox." },
    { name: 'Marco Cornacchia', company: 'Figma', initial: 'M', text: "ScreenVault is one of my favorite resources for product design and UI inspo. I love having access to a ton of 'real world examples' to see how different apps and companies handle specific UI patterns and flows." },
